/** The rates for each grade on a sheet, each from its from-date. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** A grade's rate as shown: its from-date (null: from the beginning of time) and a percent with two decimals. */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFromDate(), rate.getToDate(),
                    rate.getPct().setScale(2, RoundingMode.HALF_UP).toPlainString());
        }
    }

    /**
     * A percent is 0.00 or more with up to two decimals; a blank from-date applies from the beginning of
     * time, a blank to-date has no end, and a to-date is not before the from-date.
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from,
            LocalDate to) {

        @AssertTrue
        public boolean isEndAfterStart() {
            return from == null || to == null || !to.isBefore(from);
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, form.from(), form.to(), new BigDecimal(form.pct())));
    }

    /** Another user set the same grade's rate for the same from-date at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void rateTaken() {
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates for each grade on a sheet, each from its from-date, and the due a rate makes of an amount. */
@Service
public class RateService {

    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, ApplicationEventPublisher events) {
        this.rollup = rollup;
        this.rates = rates;
        this.sheets = sheets;
        this.events = events;
    }

    /** The sheet's rates by grade, each grade's earliest first (one with no from-date before all). */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetId(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate::getFromDate,
                        Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The sheet's rates with its today, dated settings and policy date, to find the rate in force and the live due on any date. */
    @Transactional(readOnly = true)
    public RateTable table(String sheetId) {
        return new RateTable(list(sheetId), sheets.today(sheetId), sheets.settings(sheetId),
                sheets.policyDate(sheetId));
    }

    /**
     * Set a grade's rate from a from-date (null: from the beginning of time) through a to-date (null: no
     * end), replacing the one it had from that date.
     */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        sheets.load(sheetId, user);
        BigDecimal scaled = pct.setScale(2, RoundingMode.HALF_UP);
        Rollup.Figures before = rollup.figures(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, scaled));
        } else {
            rate.setPct(scaled);
            rate.setToDate(to);
            rates.flush();
        }
        events.publishEvent(new RateChanged(sheetId, user, grade, scaled, from, to));
        rollup.changed(sheetId, user, before);
        return rate;
    }

    /** An amount times a percent, divided by 100, rounded as given to two decimals; null with no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
        return pct == null ? null : amount.multiply(pct).divide(HUNDRED).setScale(2, rounding);
    }
}

